$screenshots=[];
$screenshotsDir=__DIR__.'/../Screenshots';
if(is_dir($screenshotsDir)){
  foreach(scandir($screenshotsDir) ?: [] as $filename){
    if(preg_match('/\.(jpe?g|png|webp)$/i',$filename) && is_file($screenshotsDir.'/'.$filename)){
      $screenshots[]=$filename;
