if($_SERVER['REQUEST_METHOD']==='POST'){
check();
try{
if($action==='register'){ $name=trim($_POST['name']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$pass=$_POST['password']??'';if(!$name||!$email||strlen($pass)<8)throw new Exception('Nom, email valide et mot de passe de 8 caractères requis.');$s=$db->prepare('INSERT INTO users(name,email,password) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$db->lastInsertId(),'name'=>$name,'email'=>$email,'role'=>'user'];redirect();}
if($action==='login'){ $s=$db->prepare('SELECT * FROM users WHERE email=?');$s->execute([trim($_POST['email']??'')]);$u=$s->fetch();if(!$u||!password_verify($_POST['password']??'',$u['password']))throw new Exception('Identifiants incorrects.');session_regenerate_id(true);$_SESSION['user']=array_intersect_key($u,array_flip(['id','name','email','role']));redirect();}
if($action==='logout'){$_SESSION=[];session_regenerate_id(true);redirect();}
if($action==='admin_category'){if((user()['role']??'')!=='admin')throw new Exception('Accès refusé.');$name=trim($_POST['name']??'');if(strlen($name)<2||strlen($name)>100)throw new Exception('Nom de catégorie invalide.');$db->prepare('INSERT INTO categories(name) VALUES(?)')->execute([$name]);flash('Catégorie ajoutée.');redirect('index.php?page=admin');}
if($action==='add'){ $id=(int)($_POST['id']??0);$s=$db->prepare('SELECT id,stock FROM products WHERE id=? AND active=1');$s->execute([$id]);$p=$s->fetch();if(!$p)throw new Exception('Produit indisponible.');$_SESSION['cart'][$id]=min((int)$p['stock'],($_SESSION['cart'][$id]??0)+max(1,min(20,(int)($_POST['qty']??1))));flash('Produit ajouté au panier.');redirect('index.php?page=cart');}
if($action==='update_cart'){ $id=(int)($_POST['id']??0);$qty=(int)($_POST['qty']??0);$st=$db->prepare('SELECT stock FROM products WHERE id=? AND active=1');$st->execute([$id]);$stock=$st->fetchColumn();if($qty<=0){unset($_SESSION['cart'][$id]);}elseif($stock!==false){$_SESSION['cart'][$id]=min($qty,(int)$stock);}redirect('index.php?page=cart');}
if($action==='remove'){unset($_SESSION['cart'][(int)($_POST['id']??0)]);redirect('index.php?page=cart');}
if($action==='checkout'){if(!user())redirect('index.php?page=login');$address=trim($_POST['address']??'');if(strlen($address)<8||strlen($address)>1000)throw new Exception('Adresse de livraison invalide.');$method=$_POST['payment_method']??'';if(!in_array($method,['orange_money','airtel_money','rawbank','carte_demo'],true))throw new Exception('Mode de paiement de démonstration invalide.');$cart=$_SESSION['cart']??[];if(!$cart)throw new Exception('Panier vide.');$db->beginTransaction();$items=[];$total=0;foreach($cart as $id=>$qty){$s=$db->prepare('SELECT * FROM products WHERE id=? AND active=1 FOR UPDATE');$s->execute([(int)$id]);$p=$s->fetch();if(!$p||$qty<1||$qty>$p['stock'])throw new Exception('Stock insuffisant pour un article.');$items[]=[$p,$qty];$total+=(float)$p['price']*$qty;}$s=$db->prepare('INSERT INTO orders(user_id,total,address,status,payment_method,payment_status,payment_reference) VALUES(?,?,?,?,?,?,?)');$s->execute([user()['id'],$total,$address,'en_attente',$method,'en_attente','CMD-'.strtoupper(bin2hex(random_bytes(6)))]);$oid=$db->lastInsertId();foreach($items as [$p,$qty]){$db->prepare('INSERT INTO order_items(order_id,product_id,quantity,unit_price) VALUES(?,?,?,?)')->execute([$oid,$p['id'],$qty,$p['price']]);$db->prepare('UPDATE products SET stock=stock-? WHERE id=?')->execute([$qty,$p['id']]);}$db->commit();unset($_SESSION['cart']);flash('Commande #'.$oid.' enregistrée. Paiement non effectué : en attente de confirmation.');redirect('index.php?page=orders');}
if(str_starts_with($action,'admin_')){if((user()['role']??'')!=='admin')throw new Exception('Accès refusé.');if($action==='admin_product'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$price=(float)($_POST['price']??-1);$stock=(int)($_POST['stock']??-1);$cat=(int)($_POST['category_id']??0);$image=trim($_POST['remote_image']??'')?:trim($_POST['image']??'');$validAsset=(bool)preg_match('~^assets/products/[a-zA-Z0-9_.-]+$~',$image);$validRemote=(bool)preg_match('~^https://images\.(unsplash\.com|pexels\.com)/[a-zA-Z0-9/_?=&.%-]+$~',$image);$validScreenshot=str_starts_with($image,'../Screenshots/') && in_array(substr($image,15),$screenshots,true);if(!$name||$price<0||$stock<0||($image&&!$validAsset&&!$validScreenshot&&!$validRemote))throw new Exception('Informations produit invalides.');if($id){$db->prepare('UPDATE products SET name=?,description=?,price=?,stock=?,category_id=?,image=? WHERE id=?')->execute([$name,$_POST['description']??'',$price,$stock,$cat?:null,$image,$id]);}else{$db->prepare('INSERT INTO products(name,description,price,stock,category_id,image) VALUES(?,?,?,?,?,?)')->execute([$name,$_POST['description']??'',$price,$stock,$cat?:null,$image]);}flash('Produit enregistré.');}elseif($action==='admin_status'){$allowed=['en_attente','confirmee','expediee','livree','annulee'];if(!in_array($_POST['status']??'',$allowed,true))throw new Exception('Statut invalide.');$db->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$_POST['status'],(int)$_POST['id']]);flash('Commande mise à jour.');}elseif($action==='admin_toggle'){$db->prepare('UPDATE products SET active=1-active WHERE id=?')->execute([(int)$_POST['id']]);flash('Visibilité modifiée.');}redirect('index.php?page=admin');}
}catch(Throwable $ex){if($db->inTransaction())$db->rollBack();flash($ex instanceof PDOException?'Opération impossible (email déjà utilisé ou données invalides).':$ex->getMessage());$allowedPages=['home','shop','cart','login','register','product','account','orders','admin'];$return=$_POST['return']??'home';redirect('index.php?page='.(in_array($return,$allowedPages,true)?$return:'home'));}
}
