ing['stock']??'')?>" placeholder="Stock" required><select class="field" name="category_id"><?php foreach($categories as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach ?></select><label>Photo du produit <select class="field" id="product-image" name="image"><option value="">Aucune photo</option><?php foreach($screenshots as $photo):?><option value="<?=e('../Screenshots/'.$photo)?>"><?=e($photo)?></option><?php endforeach ?></select></label>
<p class="muted">Pour une photo Internet, colle une URL HTTPS de images.unsplash.com ou images.pexels.com dans le champ ci-dessous (elle remplace le choix de galerie si renseignée).</p><label>URL d'image Internet<input class="field" type="url" id="remote-image" name="remote_image" placeholder="https://images.unsplash.com/..." value="<?=e(str_starts_with($editing['image']??'','https://')?$editing['image']:'')?>"></label><?php if($screenshots):?><p class="muted">Choisis une photo du dossier <code>Screenshots</code> ci-dessous ; les noms et prix doivent être saisis par l'administrateur.</p><div class="screenshot-grid"><?php foreach($screenshots as $photo):?><button type="button" class="screenshot-choice" data-image-path="<?=e('../Screenshots/'.$photo)?>" title="<?=e($photo)?>"><img loading="lazy" src="<?=e('../Screenshots/'.$photo)?>" alt="Aperçu <?=e($photo)?>"><small><?=e($photo)?></small></button><?php endforeach ?></div><?php else:?><p class="muted">Aucune photo trouvée. Place le dépôt GitHub complet dans <code>htdocs</code> pour conserver le dossier Screenshots au même niveau que cette application.</p><?php endif ?><button>Enregistrer le produit</button></form><h2>Produits</h2><div class="panel table-wrap"><table><tr><th>Produit</th><th>Prix</th><th>Stock</th><th>Visible</th><th>ID</th><th>Modifier</th><th>Action</th></tr><?php foreach($db->query('SELECT * FROM products ORDER BY id DESC LIMIT 100') as $p):?><tr><td><?=e($p['name'])?></td><td><?=money($p['price'])?></td><td><?=$p['stock']?></td><td><?=$p['active']?'Oui':'Non'?></td><td><?=$p['id']?></td><td><a class="btn outline" href="?page=admin&edit=<?=$p['id']?>">Modifier</a></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="admin_toggle"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="outline">Activer / masquer</button></form></td></tr><?php endforeach ?></table></div><h2>Catégories</h2><form class="panel" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="admin_category"><label>Nouvelle catégorie<input class="field" name="name" maxlength="100" required></label><button>Ajouter la catégorie</button></form><div class="categories" style="margin:15px 0"><?php foreach($categories as $c):?><span class="chip"><?=e($c['name'])?></span><?php endforeach ?></div><h2>Commandes</h2><div class="panel table-wrap"><table><tr><th>ID</th><th>Client</th><th>Total</th><th>Statut</th></tr><?php foreach($db->query('SELECT o.*,u.name customer FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.id DESC LIMIT 100') as $o):?><tr><td>#<?=$o['id']?></td><td><?=e($o['customer'])?></td><td><?=money($o['total'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="admin_status"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status"><?php foreach(['en_attente','confirmee','expediee','livree','annulee'] as $st):?><option <?=$o['status']===$st?'selected':''?>><?=$st?></option><?php endforeach ?></select><button>OK</button></form></td></tr><?php endforeach ?></table></div><h2>Utilisateurs</h2><div class="panel table-wrap"><table><tr><th>Nom</th><th>Email</th><th>Rôle</th><th>Inscription</th></tr><?php foreach($db->query('SELECT name,email,role,created_at FROM users ORDER BY id DESC LIMIT 100') as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['role'])?></td><td><?=e($u['created_at'])?></td></tr><?php endforeach ?></table></div><?php endif;
<?php else:?><h1>Page introuvable</h1><?php endif ?></main><script>
document.querySelectorAll('[data-image-path]').forEach(button=>{
  button.addEventListener('click',()=>{
    const select=document.getElementById('product-image');
    if(!select)return;
    select.value=button.dataset.imagePath;
    document.querySelectorAll('[data-image-path]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));
    select.focus({preventScroll:true});
  });
});
 
(function(){
 const carousel=document.querySelector('[data-carousel]');if(!carousel)return;
 const slides=[...carousel.querySelectorAll('.hero-slide')];const dots=[...carousel.querySelectorAll('[data-carousel-dot]')];const counter=carousel.querySelector('[data-carousel-count]');
 let index=0,timer=null;const interval=5000;const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
 function show(next){index=(next+slides.length)%slides.length;slides.forEach((slide,i)=>{slide.classList.toggle('is-active',i===index);slide.setAttribute('aria-hidden',String(i!==index));});dots.forEach((dot,i)=>{dot.classList.toggle('is-active',i===index);if(i===index)dot.setAttribute('aria-current','true');else dot.removeAttribute('aria-current');});counter.textContent=String(index+1).padStart(2,'0');const copy=document.querySelector('[data-hero-copy]');if(copy){copy.classList.remove('hero-copy-animate');void copy.offsetWidth;copy.classList.add('hero-copy-animate');}}
 function stop(){if(timer!==null){clearInterval(timer);timer=null;}}
 function start(){stop();if(!document.hidden&&!reducedMotion.matches)timer=setInterval(()=>show(index+1),interval);}
 carousel.querySelector('[data-carousel-prev]').addEventListener('click',()=>{show(index-1);start();});
 carousel.querySelector('[data-carousel-next]').addEventListener('click',()=>{show(index+1);start();});
 dots.forEach((dot,i)=>dot.addEventListener('click',()=>{show(i);start();}));
 carousel.addEventListener('mouseenter',stop);carousel.addEventListener('mouseleave',start);
 carousel.addEventListener('focusin',stop);carousel.addEventListener('focusout',event=>{if(!carousel.contains(event.relatedTarget))start();});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();else start();});
 if(reducedMotion.addEventListener)reducedMotion.addEventListener('change',start);
 show(0);start();
})();
</script><footer><strong>DEUS COM NOS</strong><span>La mode à votre image.</span><small>© <?=date('Y')?> Tous droits réservés.</small></footer></body></html>